from test_target_priority import test, priority

unknown=priority+"aura('target',20217,'Blessing of Kings'); auras.target[1].auraInstanceID=42; "
filterapi="C_UnitAuras.IsAuraFilteredOutByInstanceID=function(u,id,filter) assert(u=='target' and id==42); if filter=='HELPFUL' then return false end return ownerFiltered end; "
test('Instance filter identifies own Kings despite missing source',unknown+filterapi+"ownerFiltered=false; refresh(); assert(not BuffTap.action.quickTarget)")
test('Instance filter identifies other Kings and allows Wisdom',unknown+filterapi+"ownerFiltered=true; refresh(); assert(BuffTap.action.quickTarget and BuffTap.action.key=='bow')")
test('Secret filter result preserves unknown ownership block',unknown+filterapi+"ownerFiltered={secret=true}; refresh(); assert(not BuffTap.action.quickTarget and BuffTap.targetDataPending)")
test('Missing instance does not imply another caster',unknown+"C_UnitAuras.IsAuraFilteredOutByInstanceID=function() return true end; refresh(); assert(not BuffTap.action.quickTarget and BuffTap.targetDataPending)")
test('Failed filter query preserves unknown ownership block',unknown+"C_UnitAuras.IsAuraFilteredOutByInstanceID=function() error('blocked') end; refresh(); assert(not BuffTap.action.quickTarget)")
test('Missing instance ID never invokes ownership query',priority+"aura('target',20217,'Blessing of Kings'); C_UnitAuras.IsAuraFilteredOutByInstanceID=function() error('must not query') end; refresh(); assert(not BuffTap.action.quickTarget)")
test('Filtered own lower blessing cannot be replaced',priority+"aura('target',19742,'Blessing of Wisdom'); auras.target[1].auraInstanceID=42; "+filterapi+"ownerFiltered=false; refresh(); assert(not BuffTap.action.quickTarget)")
test('Click refresh rechecks filtered ownership',unknown+filterapi+"ownerFiltered=true; refresh(); assert(BuffTap.action.key=='bow'); ownerFiltered=false; BuffTap.button.scripts.PreClick(BuffTap.button,'LeftButton',true); assert(not BuffTap.action)")
test('Suppressed first priority permits next safe family',priority+"BuffTap.db.helperDismiss=true; BuffTap:DismissHelper(BuffTap.action,'stronger effect rejected this action'); refresh(); assert(BuffTap.action.quickTarget and BuffTap.action.key=='bow')")
test('Suppressed own blessing never switches family',priority+"aura('target',20217,'Blessing of Kings',10,3600); auras.target[1].sourceUnit='player'; refresh(); assert(BuffTap.action.key=='bok'); BuffTap:DismissHelper(BuffTap.action,'dismissed'); refresh(); assert(not BuffTap.action.quickTarget)")
test('Suppression does not bypass disabled fallback',priority+"BuffTap.db.targetBlessingFallback=false; refresh(); BuffTap:DismissHelper(BuffTap.action,'dismissed'); refresh(); assert(not BuffTap.action.quickTarget)")
test('Known unrelated aura with secret timing permits safe buff',priority+"aura('target',999999,'Unrelated'); auras.target[1].duration={secret=true}; refresh(); assert(BuffTap.action.quickTarget and BuffTap.action.key=='bok')")
test('Known blessing with secret timing is present not missing',priority+"aura('target',20217,'Blessing of Kings'); auras.target[1].sourceUnit='other'; auras.target[1].expirationTime={secret=true}; refresh(); assert(BuffTap.action.key=='bow')")
test('Unreadable aura identity prevents blessing absence inference',priority+"auras.target={{name={secret=true},spellId={secret=true}}}; refresh(); assert(not BuffTap.action.quickTarget and BuffTap.targetDataPending)")
test('Partial scan retains readable positive coverage',"aura('player',5232,'Mark of the Wild'); auras.player[2]={secret=true}; BuffTap:InvalidateAura(); local list=BuffTap:GetAuras('player',true,true); assert(list and list.incomplete and #list==1); local def=BuffTap:FindBuff('motw'); local a=BuffTap:Resolve(def,'player'); local missing=BuffTap:Missing(def,a,list); assert(not missing); assert(BuffTap:GetAuras('player',false)==nil)")
test('Partial scan cannot authorize missing or expiring cast',"aura('player',5232,'Mark of the Wild',1,3600); auras.player[2]={secret=true}; BuffTap:InvalidateAura(); local list=BuffTap:GetAuras('player',true,true); assert(not BuffTap:Missing(BuffTap:FindBuff('motw'),BuffTap:Resolve(BuffTap:FindBuff('motw'),'player'),list)); assert(not BuffTap:Missing(BuffTap:FindBuff('thorns'),BuffTap:Resolve(BuffTap:FindBuff('thorns'),'player'),list))")
test('Strict readiness consumers reject restricted timing',"aura('player',9999,'Unrelated'); auras.player[1].duration={secret=true}; BuffTap:InvalidateAura(); assert(not BuffTap:GetAuras('player',true)); local partial=BuffTap:GetAuras('player',false,true); assert(partial and partial.timingRestricted)")

test('Full batch partial scans retain positive evidence',"C_UnitAuras.GetUnitAuras=function() return {{spellId=5232,name='Mark of the Wild',duration=1800,expirationTime=GetTime()+1800},{secret=true}} end; BuffTap:InvalidateAura(); local list=BuffTap:GetAuras('player',true,true); assert(list.incomplete and #list==1); assert(not BuffTap:Missing(BuffTap:FindBuff('motw'),BuffTap:Resolve(BuffTap:FindBuff('motw'),'player'),list))")
test('Partial scans are not cached as complete',"auras.player={{secret=true}}; BuffTap:InvalidateAura(); local a=BuffTap:GetAuras('player',false,true); assert(a.incomplete); auras.player={}; local b=BuffTap:GetAuras('player',false); assert(b and not b.incomplete)")
test('Global secrecy blocks filter ownership fallback',unknown+"C_Secrets={ShouldAurasBeSecret=function() return true end}; C_UnitAuras.IsAuraFilteredOutByInstanceID=function() error('must not query') end; refresh(); assert(not BuffTap.action)")
test('Suppression restoration returns highest eligible choice',priority+"BuffTap:DismissHelper(BuffTap.action,'dismissed'); refresh(); assert(BuffTap.action.key=='bow'); BuffTap:RestoreHelpers(); advance(.1); assert(BuffTap.action.key=='bok')")
test('Absent unrelated timing does not refresh present matching aura',priority+"aura('target',20217,'Blessing of Kings'); auras.target[1].sourceUnit='other'; auras.target[1].duration={secret=true}; refresh(); assert(BuffTap.action.key=='bow'); BuffTap.button.scripts.PreClick(BuffTap.button,'LeftButton',true); assert(BuffTap.action and BuffTap.action.key=='bow' and BuffTap.button.attrs.spell==19742)")

from test_ordered_blessings import group

test('Group priority advances past suppressed family',group+"assert(BuffTap.action.target=='party1' and BuffTap.action.key=='bok'); BuffTap:DismissHelper(BuffTap.action,'dismissed'); refresh(); assert(BuffTap.action.target=='party1' and BuffTap.action.key=='bom')")
test('Fixed group assignment does not advance after suppression',group+"BuffTap.db.blessingClasses.WARRIOR='bok'; refresh(); BuffTap:DismissHelper(BuffTap.action,'dismissed'); refresh(); assert(not BuffTap.action or BuffTap.action.target~='party1')")
test('Group own blessing remains protected after suppression',group+"aura('party1',20217,'Blessing of Kings',10,3600); auras.party1[1].sourceUnit='player'; refresh(); BuffTap:DismissHelper(BuffTap.action,'dismissed'); refresh(); assert(not BuffTap.action or BuffTap.action.target~='party1')")
